{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소보다 높은 용량의 처방에서 투약보다 처방 확인을 우선한 안전 판단의 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자에게 평소 두 배 용량의 진통제가 처방되었다.",
          "task": "처방된 용량을 그대로 투약해도 되는지 판단해야 했다.",
          "action": "용량의 안전성이 확인되지 않았다고 판단해 투약을 멈추고 담당의에게 확인했다.",
          "result": "담당의 확인으로 입력 오류를 발견해 잘못된 용량의 투약을 막았다."
        },
        "expectedEvidence": [
          "증량 가능성에도 처방 확인을 우선한 이유를 설명한다.",
          "담당의에게 확인한 내용과 입력 오류 확인 결과를 제시한다."
        ]
      },
      "question": "푸른결종합병원에서 두 배 용량의 진통제 투약을 멈추셨던데요. 통증에 따른 증량일 수도 있는 처방을 바로 투약하지 않은 이유는 무엇이었나요?",
      "answerTip": "당시 실제로 한 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방이 있다는 사실만으로 용량의 안전성을 확신할 수 없었던 이유를 당시 상황에 근거해 설명한다.",
            "담당의에게 확인한 내용과 입력 오류로 확인된 결과가 구체적으로 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소보다 높은 용량이라 확인이 필요했다고 답하지만 당시 판단 근거나 확인 내용은 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 이유를 설명하지 못하거나 처방이 있으면 확인 없이 투약해도 된다고 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태를 다음 근무자가 이어서 판단하도록 투약 시각을 인수인계 정보로 선택한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동 사고 보고서에서 첫 보행 환자의 낙상이 교대 시간대에 몰린 점을 확인했다.",
          "task": "다음 근무자에게 빠짐없이 전달할 환자 정보를 정해야 했다.",
          "action": "환자 상태를 이어서 판단하는 데 필요한 정보로 진통제 투여 시각을 인수인계표에 추가했다.",
          "result": "다음 근무자가 투여 시점에 비추어 환자 상태를 관찰할 수 있게 한다."
        },
        "expectedEvidence": [
          "투여 여부만이 아니라 시각까지 인계해야 하는 이유를 설명한다.",
          "투여 시각이 다음 근무자의 환자 상태 관찰에 주는 차이를 구체화한다."
        ]
      },
      "question": "푸른결종합병원에서 낙상 예방 인수인계표에 진통제 투여 시각을 추가하셨던데요. 투여 여부만이 아니라 시각까지 다음 근무자에게 넘겨야 한다고 본 이유는 무엇이었나요?",
      "answerTip": "당시 판단을 떠올릴 수 있는 구체적인 맥락으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투여 여부만으로 부족한 이유를 교대 후 환자 상태를 이어서 관찰해야 하는 상황과 연결해 설명한다.",
            "투여 시각을 알 때 다음 근무자가 환자 상태를 판단하는 데 생기는 차이를 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "투여 시각을 인계해야 하는 이유는 답하지만 환자 상태 관찰과의 연결은 일반적인 설명에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투여 시각을 전달해야 하는 이유를 설명하지 못하거나 낙상 건수 감소만 반복한다."
          ]
        }
      }
    }
  ]
}

